require_once __DIR__.'/includes/letters.php';LetterModule::requireCapability('settings');$pageTitle='سربرگ‌های سازمانی';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/letter-letterheads.php');}try{$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان سربرگ الزامی است.');$current=$id?Database::fetch('SELECT * FROM letter_letterheads WHERE id=?',[$id]):[];$logo=$current['logo_path']??null;$background=$current['background_path']??null;$backgroundMime=$current['background_mime']??null;if(($_FILES['logo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$up=letterhead_upload($_FILES['logo'],'logo');if(!$up['ok'])throw new InvalidArgumentException($up['error']);$logo=$up['file_path'];}if(($_FILES['background']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$up=letterhead_upload($_FILES['background'],'background',true);if(!$up['ok'])throw new InvalidArgumentException($up['error']);$background=$up['file_path'];$backgroundMime=$up['mime_type'];}$active=isset($_POST['is_active'])?1:0;$default=$active&&isset($_POST['is_default'])?1:0;$mm=static fn(string $key,int $fallback):int=>max(0,min(40,(int)($_POST[$key]??$fallback)));$data=[$title,trim((string)($_POST['company_name']??'')),trim((string)($_POST['contact_info']??'')),$logo,$background,$backgroundMime,trim((string)($_POST['watermark_text']??'')),LetterModule::sanitizeHtml($_POST['header_html']??''),LetterModule::sanitizeHtml($_POST['footer_html']??''),$mm('margin_top_mm',18),$mm('margin_right_mm',18),$mm('margin_bottom_mm',18),$mm('margin_left_mm',18),$mm('header_position_mm',0),$mm('footer_position_mm',0),$default,$active];$pdo=Database::connection();$pdo->beginTransaction();if($default)Database::execute('UPDATE letter_letterheads SET is_default=0 WHERE is_default=1');if($id)Database::execute('UPDATE letter_letterheads SET title=?,company_name=?,contact_info=?,logo_path=?,background_path=?,background_mime=?,watermark_text=?,header_html=?,footer_html=?,margin_top_mm=?,margin_right_mm=?,margin_bottom_mm=?,margin_left_mm=?,header_position_mm=?,footer_position_mm=?,is_default=?,is_active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else{Database::execute('INSERT INTO letter_letterheads(title,company_name,contact_info,logo_path,background_path,background_mime,watermark_text,header_html,footer_html,margin_top_mm,margin_right_mm,margin_bottom_mm,margin_left_mm,header_position_mm,footer_position_mm,is_default,is_active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);$id=(int)Database::lastInsertId();}$pdo->commit();Auth::log((int)Auth::user()['id'],$current?'letterhead_updated':'letterhead_created','letter_letterheads',$id);flash('سربرگ ذخیره شد.');}catch(InvalidArgumentException $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'danger');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Letterhead: '.$e->getMessage());flash('ذخیره سربرگ انجام نشد.','danger');}redirect('/admin/letter-letterheads.php');}
