eld"><span>فاصله فوتر از پایین (mm)</span><input type="number" min="0" max="40" name="footer_position_mm" value="<?=e($edit['footer_position_mm']??'0')?>"></label><?php foreach(['margin_top_mm'=>'بالا','margin_right_mm'=>'راست','margin_bottom_mm'=>'پایین','margin_left_mm'=>'چپ'] as $key=>$label):?><label class="form-field"><span>حاشیه <?=$label?> (mm)</span><input type="number" min="5" max="40" name="<?=$key?>" value="<?=e($edit[$key]??'18')?>"></label><?php endforeach?><label class="form-field grid-span-2"><span>HTML هدر (اختیاری و پالایش‌شده)</span><textarea name="header_html"><?=e($edit['header_html']??'')?></textarea></label><label class="form-field grid-span-2"><span>HTML فوتر (اختیاری و پالایش‌شده)</span><textarea name="footer_html"><?=e($edit['footer_html']??'')?></textarea></label></div><div class="form-actions"><button class="btn btn-primary">ذخیره سربرگ</button><?php if($edit):?><a class="btn" href="/admin/letter-letterheads.php">انصراف</a><?php endif?></div></form></section>
